/* Set --slider-thumb and --slider-track to resize. The track is inset by half a thumb, so a thumb at either limit stays inside the box. */
.root, .field { --slider-thumb: 22px; --slider-track: 6px; display: grid; width: 100%; min-width: 0; color: var(--foreground); font-size: var(--text-sm); line-height: var(--leading-body); letter-spacing: var(--tracking-body); user-select: none; -webkit-user-select: none; }
.header, .head { display: flex; min-width: 0; align-items: baseline; justify-content: space-between; gap: var(--space-4); margin-bottom: var(--space-1); }
.label { min-width: 0; font-weight: 500; }
.readout, .valueText { display: inline-flex; flex: none; align-items: center; gap: .3em; color: var(--text-secondary); font-variant-numeric: tabular-nums; white-space: nowrap; }
.dash { color: var(--text-muted); }
/* Adornments carry their own space, so an empty column costs nothing. */
.body, .trackWrapper { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; position: relative; }
.start { display: flex; grid-area: 1 / 1; margin-right: var(--space-3); }
.end { display: flex; grid-area: 1 / 3; margin-left: var(--space-3); }
/* The whole row takes the press; vertical pans still scroll the page on touch. */
.control { position: relative; grid-area: 1 / 2; height: var(--control-height-md); cursor: pointer; touch-action: pan-y; -webkit-tap-highlight-color: transparent; }
.track { position: absolute; top: 50%; right: calc(var(--slider-thumb) / 2); left: calc(var(--slider-thumb) / 2); height: var(--slider-track); margin-top: calc(var(--slider-track) / -2); border-radius: var(--radius-pill); background: var(--control-track); }
/* The fill spans the track and is revealed by a clip that follows the thumbs on the same frame. */
.fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: inherit; background: var(--control-fill); }
.tick { position: absolute; top: 50%; width: 4px; height: 4px; margin: -2px 0 0 -2px; border-radius: var(--radius-pill); background: color-mix(in oklch, var(--foreground) 30%, transparent); }
.fill .tick { background: color-mix(in oklch, var(--control-glyph) 60%, transparent); }
.thumbs { position: absolute; inset: 0 calc(var(--slider-thumb) / 2); container-type: inline-size; pointer-events: none; }
/* Each layer is as wide as the track and slides by a percentage of itself */
.thumbLayer, .thumbSlot { position: absolute; top: 0; bottom: 0; width: 0; }
/* Centering uses the translate property */
.thumb { position: absolute; top: 50%; left: 0; box-sizing: border-box; width: var(--slider-thumb); height: var(--slider-thumb); translate: -50% -50%; border: 0; border-radius: var(--radius-pill); background: var(--control-thumb); box-shadow: var(--control-thumb-shadow); pointer-events: auto; cursor: grab; outline: 0 solid transparent; transition: box-shadow var(--duration-fast) var(--ease-standard); }
.thumb::after { content: ""; position: absolute; inset: -11px; border-radius: inherit; }
.thumb:focus-visible:not([data-quiet]) { outline: 3px solid var(--focus-ring); outline-offset: 2px; }
.root[data-dragging], .root[data-dragging] .control, .root[data-dragging] .thumb { cursor: grabbing; }
.bubbleAnchor { --edge: calc(var(--slider-thumb) / 2); position: absolute; left: 0; bottom: calc(50% + var(--slider-thumb) / 2 + 8px); display: flex; translate: -50% 0; pointer-events: none; }
@media (pointer: coarse) { .bubbleAnchor { bottom: calc(50% + var(--slider-thumb) / 2 + 18px); } }
.bubble { display: inline-flex; min-height: 1.75rem; align-items: center; padding: 0 var(--space-3); border: 1px solid color-mix(in oklch, var(--background) 14%, var(--foreground)); border-radius: var(--radius-pill); background: var(--foreground); color: var(--background); box-shadow: var(--shadow-raised); font-size: var(--text-sm); font-weight: 500; white-space: nowrap; transform-origin: 50% 100%; }
.marks { position: relative; grid-area: 2 / 2; height: 1.25rem; margin: calc(var(--space-1) * -1) calc(var(--slider-thumb) / 2) 0; color: var(--text-muted); font-size: var(--text-xs); font-variant-numeric: tabular-nums; }
.markLabel { position: absolute; top: 0; translate: -50% 0; white-space: nowrap; cursor: pointer; transition: color var(--duration-fast) var(--ease-standard); }
.markLabel[data-edge="start"] { translate: max(-50%, calc(var(--slider-thumb) / -2)) 0; }
.markLabel[data-edge="end"] { translate: min(-50%, calc(-100% + var(--slider-thumb) / 2)) 0; }
.markLabel[data-on] { color: var(--text-secondary); }
@media (hover: hover) and (pointer: fine) { .markLabel:hover { color: var(--foreground); } }
.root[data-disabled], .field[data-disabled] { opacity: .5; }
.root[data-disabled] .control, .root[data-disabled] .thumb, .root[data-disabled] .markLabel { cursor: not-allowed; }
@media (prefers-reduced-motion: reduce) { .thumb, .markLabel { transition: none; } }
